from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[1];PREV=ROOT/'handoff/chatgpt-n3-central-local-funding-accounts-20261122'
def dump(p,rs):
 keys=list(dict.fromkeys(k for r in rs for k in r))
